def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def col_of(name: str) -> int:
        return ord(name[0]) - ord("A")

    def row_of(name: str) -> int:
        return int(name[1:])

    def expand(a: str, b: str):
        c1, c2 = col_of(a), col_of(b)
        r1, r2 = row_of(a), row_of(b)
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                yield chr(ord("A") + c) + str(r)

    def idiv(a: int, b: int):
        if b == 0:
            return "#DIV/0!"
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            return -q
        return q

    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def skip(self):
            while self.i < self.n and self.s[self.i] == " ":
                self.i += 1

        def peek(self) -> str:
            self.skip()
            return self.s[self.i] if self.i < self.n else ""

        def eat(self, ch: str):
            self.skip()
            self.i += 1

        def parse_number(self) -> int:
            self.skip()
            j = self.i
            while j < self.n and self.s[j].isdigit():
                j += 1
            v = int(self.s[self.i:j])
            self.i = j
            return v

        def parse_cell(self) -> str:
            self.skip()
            j = self.i + 1
            while j < self.n and self.s[j].isdigit():
                j += 1
            name = self.s[self.i:j]
            self.i = j
            return name

        def parse_cmp(self) -> str:
            self.skip()
            two = self.s[self.i:self.i + 2]
            if two in ("<>", "<=", ">="):
                self.i += 2
                return two
            op = self.s[self.i]
            self.i += 1
            return op

        def parse_expr(self):
            return self.parse_add()

        def parse_add(self):
            left = self.parse_mul()
            while self.peek() in "+-":
                op = self.s[self.i]
                self.i += 1
                right = self.parse_mul()
                left = ("bin", op, left, right)
            return left

        def parse_mul(self):
            left = self.parse_unary()
            while self.peek() in "*/":
                op = self.s[self.i]
                self.i += 1
                right = self.parse_unary()
                left = ("bin", op, left, right)
            return left

        def parse_unary(self):
            if self.peek() == "-":
                self.i += 1
                return ("neg", self.parse_unary())
            return self.parse_atom()

        def parse_atom(self):
            self.skip()
            if self.s[self.i].isdigit():
                return ("num", self.parse_number())
            if self.s[self.i] == "(":
                self.i += 1
                inner = self.parse_expr()
                self.eat(")")
                return inner
            if self.s.startswith("SUM", self.i):
                return self.parse_agg("SUM", 3)
            if self.s.startswith("MIN", self.i):
                return self.parse_agg("MIN", 3)
            if self.s.startswith("MAX", self.i):
                return self.parse_agg("MAX", 3)
            if self.s.startswith("IF", self.i):
                return self.parse_if()
            return ("cell", self.parse_cell())

        def parse_if(self):
            self.i += 2
            self.eat("(")
            left = self.parse_expr()
            op = self.parse_cmp()
            right = self.parse_expr()
            self.eat(",")
            then_b = self.parse_expr()
            self.eat(",")
            else_b = self.parse_expr()
            self.eat(")")
            return ("if", left, op, right, then_b, else_b)

        def parse_agg(self, name: str, n: int):
            self.i += n
            self.eat("(")
            args = [self.parse_arg()]
            while self.peek() == ",":
                self.i += 1
                args.append(self.parse_arg())
            self.eat(")")
            return (name, args)

        def parse_arg(self):
            self.skip()
            i0 = self.i
            if (
                i0 < self.n
                and self.s[i0].isalpha()
                and i0 + 1 < self.n
                and self.s[i0 + 1].isdigit()
            ):
                c1 = self.parse_cell()
                if self.peek() == ":":
                    self.i += 1
                    c2 = self.parse_cell()
                    return ("range", c1, c2)
                self.i = i0
            return self.parse_expr()

    def compare(a: int, op: str, b: int) -> bool:
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = ev(node[1])
            if isinstance(v, str):
                return v
            return -v
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            lv = ev(left)
            if isinstance(lv, str):
                return lv
            rv = ev(right)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return idiv(lv, rv)
        if kind in ("SUM", "MIN", "MAX"):
            vals = []
            for arg in node[1]:
                if arg[0] == "range":
                    for name in expand(arg[1], arg[2]):
                        if name not in cells:
                            continue
                        v = eval_cell(name)
                        if isinstance(v, str):
                            return v
                        vals.append(v)
                else:
                    v = ev(arg)
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            if not vals:
                return 0
            if kind == "SUM":
                return sum(vals)
            if kind == "MIN":
                return min(vals)
            return max(vals)
        left, op, right, then_b, else_b = node[1], node[2], node[3], node[4], node[5]
        lv = ev(left)
        if isinstance(lv, str):
            return lv
        rv = ev(right)
        if isinstance(rv, str):
            return rv
        return ev(then_b if compare(lv, op, rv) else else_b)

    def eval_cell(name: str):
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            result = ev(Parser(raw[1:]).parse_expr())
        else:
            result = int(raw)
        visiting.remove(name)
        memo[name] = result
        return result

    for name in cells:
        eval_cell(name)
    return {name: memo[name] for name in cells}
